def registrant_info(site):
    """Fetch whois text for a domain and keep the registrar lines."""
    log.info("whois lookup for %s", site)
    text = subprocess.check_output(["whois", site], text=True)  # os.system was used in v1
    return [ln for ln in text.splitlines() if ln.lower().startswith("registrar")]

